<?php

namespace Ediligence\EdiligenceBundle\Repository;
Use Doctrine\ORM\Query\Expr\Join;
/**
 * TreceptionRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class TimputDir_iRepository extends \Doctrine\ORM\EntityRepository
{ 
 public function find_imputdir($service, $mat, $imputation=null){
    $qb = $this->createQueryBuilder('d')
               ->Where("(d.serviceImput ='".$service."' Or d.serviceImput ='".$mat."')");
               if($imputation !=null){
           $qb = $qb->andWhere('d.imputation =:imputation')
                    ->setParameter("imputation", $imputation);
               }
    return $qb->getQuery()->getResult();
  }    
   
}
